import React, { forwardRef, ReactNode, useMemo } from 'react';
import { isElement } from 'react-is';
import styled from 'styled-components';

import { MenuIcon } from '@dynatrace/strato-icons';

import { ActionGroup } from './action-group/ActionGroup.js';
import { AppIcon } from './AppIcon.js';
import { AppNavLink } from './AppNavLink.js';
import { AppNavLinkInternal } from './AppNavLinkInternal.js';
import { useActionItemsContext } from './hooks/useActionItemsContext.js';
import { useNavItemsContext } from './hooks/useNavItemsContext.js';
import { NavItem } from './NavItem.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';
// #region Typings
// Disabled in order for API extractor not to complain about exporting
// With children from the package
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface AppHeaderNavItemsProps
  extends WithChildren,
    StylingProps,
    DataTestId {}

type SlotsType = {
  items: ReactNode[];
  navlink: ReactNode;
};
// #endregion

// #region Styled Components
const StyledNavItems = styled(ActionGroup)({
  minWidth: 0,
  ' a': getTextStyle('base-emphasized'),
});
// #endregion

/**
 * The navigation items section of the AppHeader.
 */
export const NavItems = forwardRef<HTMLDivElement, AppHeaderNavItemsProps>(
  (props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: AppHeaderNavItemsProps = props;

    const slots = useMemo(() => {
      const slots: SlotsType = { items: [], navlink: null };

      for (const child of React.Children.toArray(children)) {
        if (isElement(child) && child.type === NavItem) {
          slots.items.push(child);
        } else if (isElement(child) && child.type === AppNavLink) {
          slots.navlink = React.cloneElement(child, {
            ..._mergeProps(child.props, { pin: true }),
          });
        }
      }

      return slots;
    }, [children]);

    const { hasNavItems, isNavOverflowing, setIsNavOverflowing } =
      useNavItemsContext();
    const { hasActions, isActionItemsCollapsed } = useActionItemsContext();

    return (
      <StyledNavItems
        ref={forwardedRef}
        data-testid={dataTestId}
        role="navigation"
        collapsible={
          isActionItemsCollapsed && hasNavItems // if there are no nav items, it shouldn't collapse
        }
        flexGrow={
          (isActionItemsCollapsed && isNavOverflowing) ||
          !(hasActions && hasNavItems)
            ? 1
            : 0
        }
        triggerIcon={<MenuIcon />}
        onOverflowChange={setIsNavOverflowing}
        rovingFocus={false}
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        {slots.navlink ?? (
          <AppNavLinkInternal pin>
            <AppIcon />
          </AppNavLinkInternal>
        )}
        {slots.items}
      </StyledNavItems>
    );
  },
);

(NavItems as typeof NavItems & { displayName: string }).displayName =
  'AppHeader.NavItems';
